-- 2026-08-10  The tooling dataset, from the development copy into production.
--
-- Production's nine tools_* tables are EMPTY. Every row the tooling module has ever had - 8
-- categories, 13 processes, 45 parts, 309 tool types, 345 stockable items, 138 assignments and
-- 185 opening movements - lives on the development copy and nowhere else. This file carries them
-- across. It is data only: the shape is already right on production and this changes none of it.
--
-- WHY TRIGGERS ARE OFF FOR THE LOAD. Production has tools_txn_apply_t, which adds new.qty to
-- tools_item.qty_on_hand on every insert. The development copy has no such trigger, and its
-- qty_on_hand was backfilled once by 2026-08-05_tooling_access.sql - it already reads 2,484,
-- exactly the sum of the ledger being loaded. Insert the ledger with the trigger live and every
-- quantity is counted twice: 4,968 pieces of stock that do not exist. session_replication_role
-- = replica silences it, and the two numbers arrive already agreeing. It also defers the foreign
-- keys, which is why the COPY order below does not have to be a topological sort.
--
-- WHY THE SEQUENCE RESETS ARE NOT pg_dump's. A data-only dump names the sequences of the database
-- it came FROM, and this pair has not been through the same renames: the development copy still
-- calls them out_tool_id_seq and out_part_id_seq, production calls them tools_master_id_seq and
-- tools_part_id_seq. Replaying the dump's own setval lines against production fails on every one.
-- pg_get_serial_sequence asks the target what its sequence is called, so this works on either.
--
-- The two code sequences (tools_master_code_seq, tools_item_code_seq) are deliberately NOT set
-- here. They do not exist on production yet; sql/2026-08-06_tooling_codes_and_intake.sql creates
-- them and recomputes both from the data, so it must run AFTER this file. Order and verification
-- are in sql/2026-08-10_tooling_to_production.md.
--
-- Verified before writing: 0 rows break the txn sign rule, 0 orphan foreign keys, 0 duplicates
-- under the partial unique index, and every code matches FTL-nnnn / FTI-nnnnn.

BEGIN;
SET LOCAL session_replication_role = replica;

--
-- PostgreSQL database dump
--

-- Dumped from database version 15.8
-- Dumped by pg_dump version 15.8

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Data for Name: tools_category; Type: TABLE DATA; Schema: public; Owner: -
--



--
-- Data for Name: tools_master; Type: TABLE DATA; Schema: public; Owner: -
--



--
-- Data for Name: tools_item; Type: TABLE DATA; Schema: public; Owner: -
--



--
-- Data for Name: tools_part; Type: TABLE DATA; Schema: public; Owner: -
--



--
-- Data for Name: tools_part_demand; Type: TABLE DATA; Schema: public; Owner: -
--



--
-- Data for Name: tools_process; Type: TABLE DATA; Schema: public; Owner: -
--



--
-- Data for Name: tools_profile; Type: TABLE DATA; Schema: public; Owner: -
--



--
-- Data for Name: tools_txn; Type: TABLE DATA; Schema: public; Owner: -
