--
-- PostgreSQL database dump complete
--


--
-- Identity sequences, asked of the target rather than assumed.
--
SELECT setval(pg_get_serial_sequence('public.tools_master','id'),      coalesce((SELECT max(id) FROM public.tools_master),1),      true);
SELECT setval(pg_get_serial_sequence('public.tools_item','id'),        coalesce((SELECT max(id) FROM public.tools_item),1),        true);
SELECT setval(pg_get_serial_sequence('public.tools_part','id'),        coalesce((SELECT max(id) FROM public.tools_part),1),        true);
SELECT setval(pg_get_serial_sequence('public.tools_part_demand','id'), coalesce((SELECT max(id) FROM public.tools_part_demand),1), true);
SELECT setval(pg_get_serial_sequence('public.tools_txn','id'),         coalesce((SELECT max(id) FROM public.tools_txn),1),         true);
SELECT setval(pg_get_serial_sequence('public.tools_usage','id'),       coalesce((SELECT max(id) FROM public.tools_usage),1),       true);

SET LOCAL session_replication_role = DEFAULT;
COMMIT;
